.book-guest{color:var(--muted); font-size:13px}
.book-meta{color:var(--muted); font-size:12px; margin-top:4px}
.book-actions{display:flex; gap:8px; flex-wrap:wrap; align-items:center}

/* Tables */
.tbl-wrap{background:#fff; border:1px solid var(--line); border-radius:var(--radius); overflow:auto; box-shadow:var(--shadow)}
table{width:100%; border-collapse:collapse; min-width:620px}
th,td{text-align:left; padding:12px 14px; border-bottom:1px solid var(--line); font-size:14px; vertical-align:middle}
th{background:var(--soft-2); font-size:12px; text-transform:uppercase; letter-spacing:.4px; color:var(--ink-2)}
tbody tr:last-child td{border-bottom:0}
.actions-cell{display:flex; gap:6px; flex-wrap:wrap}

/* Modal */
.overlay{position:fixed; inset:0; background:rgba(6,36,42,.55); display:grid; place-items:center;
  padding:20px; z-index:50}
.modal{background:#fff; border-radius:16px; width:100%; max-width:440px; padding:22px; box-shadow:0 30px 60px rgba(0,0,0,.35)}
.modal h3{font-size:18px; margin-bottom:4px}
.modal .sub{color:var(--muted); font-size:14px; margin-bottom:14px}
.modal-actions{display:flex; gap:10px; margin-top:18px}
.modal-actions .btn{flex:1}
.two-col{display:grid; grid-template-columns:1fr 1fr; gap:12px}

/* Toast */
.toasts{position:fixed; bottom:20px; left:50%; transform:translateX(-50%); z-index:100;
  display:flex; flex-direction:column; gap:10px; align-items:center}
.toast{background:#0c2f38; color:#fff; padding:12px 18px; border-radius:10px; font-size:14px;
  font-weight:600; box-shadow:0 12px 30px rgba(0,0,0,.3); animation:pop .2s ease}
.toast.err{background:var(--bad)}
.toast.ok{background:var(--ok)}
@keyframes pop{from{opacity:0; transform:translateY(8px)} to{opacity:1; transform:none}}

.empty{text-align:center; color:var(--muted); padding:40px 10px}
.empty .big{font-size:40px; margin-bottom:8px}

/* Manager tabs */
.mgr-tabs{display:flex; gap:6px; margin-bottom:18px; flex-wrap:wrap}
.mgr-tab{border:1px solid var(--line); background:#fff; padding:9px 16px; border-radius:9px;
  font-weight:700; cursor:pointer; color:var(--muted)}
.mgr-tab.active{background:var(--ink); color:#fff; border-color:var(--ink)}

@media(max-width:560px){
  .topbar-inner{flex-wrap:wrap}
  .filterbar{flex-direction:column; align-items:stretch}
  .filterbar .field{min-width:0}
  .pill-count{margin:6px 0 0}
  .two-col{grid-template-columns:1fr}
}

